use tsr_ast::{NodeTable, SyntaxKind};
use symbol_access::CheckerSymbols;
mod symbol_access;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct TypeId(u32);
struct Checker<'a,'n> {
    symbols: CheckerSymbols<'a>,
    nodes: &'n NodeTable,
}
impl Checker<'_,'_> {
    pub(crate) fn compare_symbols_ref(
        &mut self,
        a: &crate::symbol_access::SymbolRef,
        b: &crate::symbol_access::SymbolRef,
    ) -> std::cmp::Ordering {
        if a == b {
            self.symbols.view(a).expect("selected sort owner");
            return std::cmp::Ordering::Equal;
        }
        let position = |symbol: &crate::symbol_access::SymbolRef| {
            let view = self.symbols.view(symbol).expect("selected sort owner");
            let position = view.declarations().first().map(|&declaration| {
                let mut file = declaration;
                let mut current = Some(declaration);
                while let Some(node) = current {
                    if self.nodes.kind(node) == SyntaxKind::SourceFile {
                        file = node;
                        break;
                    }
                    current = self.nodes.parent(node);
                }
                (file, self.nodes.span(declaration).start)
            });
            (position.is_none(), position)
        };
        let ordering = position(a).cmp(&position(b)).then_with(|| {
            self.symbols
                .view(a)
                .expect("selected sort owner")
                .name()
                .cmp(self.symbols.view(b).expect("selected sort owner").name())
        });
        if ordering != std::cmp::Ordering::Equal {
            return ordering;
        }
        self.symbols
            .view(a)
            .expect("selected sort owner")
            .identity_id()
            .cmp(&self.symbols.view(b).expect("selected sort owner").identity_id())
    }

}
#[cfg(test)]
mod tests {
    use super::*;
    use tsr_binder::{SymbolFlags,SymbolStore};
    #[test]
    fn selected_comparator_keeps_private_copies_distinct_and_stable() {
        let mut program=SymbolStore::new();
        let raw=program.create("same",SymbolFlags::PROPERTY);
        let nodes=NodeTable::default();
        let mut checker=Checker { symbols: CheckerSymbols::new(&program,TypeId(0)), nodes:&nodes };
        let raw=checker.symbols.bound(raw).unwrap();
        let copy=checker.symbols.clone_module_symbol(&raw).unwrap();
        let twin=checker.symbols.clone_module_symbol(&raw).unwrap();
        let other=checker.symbols.new_symbol(SymbolFlags::PROPERTY, "aaa".into(), symbol_access::CheckFlags::empty());
        assert!(checker.compare_symbols_ref(&other,&copy).is_lt());
        assert!(checker.compare_symbols_ref(&copy,&other).is_gt());
        assert!(checker.compare_symbols_ref(&twin,&copy).is_lt());
        assert!(checker.compare_symbols_ref(&copy,&twin).is_gt());
        assert!(checker.compare_symbols_ref(&twin,&raw).is_lt());
        assert!(checker.compare_symbols_ref(&copy,&raw).is_lt());
        for _ in 0..3 {
            assert!(checker.compare_symbols_ref(&twin,&copy).is_lt());
            assert!(checker.compare_symbols_ref(&copy,&twin).is_gt());
            assert!(checker.compare_symbols_ref(&copy,&copy).is_eq());
        }
    }
    #[test]
    fn selected_comparator_reads_the_copy_declaration_before_its_source() {
        let arena=tsr_core::Arena::new();
        let text="const laterName = 1; const earlierName = 2;";
        let parsed=tsr_parser::parse(&arena,text);
        let bound=tsr_binder::bind(&arena,parsed.source_file,&parsed.nodes,tsr_binder::FileInfo { name:"order.ts",text });
        let symbols=bound.symbols();
        let first=symbols.iter().find(|(_,s)| s.name=="laterName").unwrap().0;
        let second=symbols.iter().find(|(_,s)| s.name=="earlierName").unwrap().0;
        let mut checker=Checker { symbols: CheckerSymbols::new(symbols,TypeId(0)), nodes:&parsed.nodes };
        let first=checker.symbols.bound(first).unwrap();
        let second=checker.symbols.bound(second).unwrap();
        let copy=checker.symbols.new_symbol(SymbolFlags::PROPERTY,"aaa".into(),symbol_access::CheckFlags::empty());
        checker.symbols.append_declaration(&copy,checker.symbols.view(&second).unwrap().declarations()[0]).unwrap();
        assert!(checker.compare_symbols_ref(&first,&second).is_lt());
        assert!(checker.compare_symbols_ref(&first,&copy).is_lt());
        assert!(checker.compare_symbols_ref(&copy,&first).is_gt());
        let empty=checker.symbols.new_symbol(SymbolFlags::PROPERTY,"aaa".into(),symbol_access::CheckFlags::empty());
        assert!(checker.compare_symbols_ref(&copy,&empty).is_lt());
    }
}

